            alt="photoOfProducts"
            className={style.img}
          />
          <img
            src={filteredData[0]?.images[2]}
            alt="photoOfProducts"
            className={style.img}
          />
        </div>
        <div className={style.details}>
          <h2>{filteredData[0]?.title}</h2>
          <p>{filteredData[0]?.description}</p>
          <h4>$ {filteredData[0]?.price}</h4>
        </div> */}
      </div>
    </div>
  );
};

export default EachProduct;
